sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform shader backdrop;
uniform float threshold;
uniform float feather;
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    if (c.a <= 0.0) return c;
    half4 b = backdrop.eval(coord);
    float3 under = b.a > 0.0 ? float3(b.rgb) / float(b.a) : float3(0.0);
    float d = length(float3(c.rgb) / float(c.a) - under);
    float f = max(feather, 0.0001);
    float keep = clamp((d - threshold + f) / f, 0.0, 1.0);
    return c * half(keep);
}
